insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('juju-cien-t01','ciencias','Como percebemos o mundo: som e audição','treino','Para existir um som, precisamos de:','["Luz e cor", "Algo que vibre e um meio para o som viajar", "Só de silêncio", "Uma tela e um fone"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t02','ciencias','Como percebemos o mundo: som e audição','treino','Qual órgão do corpo é responsável pela audição?','["A orelha", "O nariz", "A língua", "A pele"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t03','ciencias','Como percebemos o mundo: som e audição','treino','Dentro da orelha existe uma pele bem fininha que vibra quando o som chega. Como ela se chama?','["Lóbulo", "Estribo", "Tímpano", "Nariz"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t04','ciencias','Como percebemos o mundo: som e audição','treino','Quem "entende" o som que ouvimos, descobrindo se é um latido ou uma música?','["O tímpano", "O lóbulo da orelha", "A boca", "O cérebro"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t05','ciencias','Como percebemos o mundo: som e audição','treino','Martelo, bigorna e estribo são:','["Ferramentas de construção", "Três ossinhos bem pequenos dentro da orelha", "Partes do nariz", "Instrumentos musicais"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t06','ciencias','Propriedades do som','treino','Você reconhece a voz da sua mãe no telefone, mesmo sem ver quem está falando. Que propriedade do som ajuda nisso?','["Duração", "Intensidade", "Timbre", "Altura"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t07','ciencias','Propriedades do som','treino','Um cochicho e um grito são diferentes principalmente na:','["Intensidade (fraco ou forte)", "Duração", "Timbre", "Cor"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t08','ciencias','Propriedades do som','treino','O piado de um passarinho é fino e o mugido de uma vaca é grosso. Essa diferença está na:','["Duração", "Intensidade", "Altura (agudo ou grave)", "Distância"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t09','ciencias','Propriedades do som','treino','O apito do trem que dura muito tempo e um "bip" rapidinho do micro-ondas são diferentes na:','["Altura", "Duração", "Timbre", "Intensidade"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t10','ciencias','Propriedades do som','treino','Quando abaixamos o volume da televisão, mudamos a:','["Altura", "Duração", "Timbre", "Intensidade"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t11','ciencias','Propriedades do som','treino','Um som agudo é um som:','["Fino", "Grosso", "Bem fraco", "Que dura muito"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t12','ciencias','Instrumentos musicais e seus diferentes sons','treino','Na flauta, o som é produzido:','["Batendo com baquetas", "Pelo ar que vibra dentro de um tubo", "Pela vibração das cordas", "Chacoalhando sementes"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t13','ciencias','Instrumentos musicais e seus diferentes sons','treino','O violão é um instrumento de:','["Sopro", "Percussão", "Corda", "Teclado elétrico"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t14','ciencias','Instrumentos musicais e seus diferentes sons','treino','Qual destes é um instrumento de percussão?','["Tambor", "Violino", "Trompete", "Harpa"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t15','ciencias','Instrumentos musicais e seus diferentes sons','treino','Qual destes instrumentos é de sopro?','["Pandeiro", "Contrabaixo", "Xilofone", "Saxofone"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t16','ciencias','A natureza dos diferentes sons','treino','Qual destes é um som da natureza?','["Buzina de carro", "Canto de um pássaro", "Sirene de ambulância", "Campainha"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t17','ciencias','A natureza dos diferentes sons','treino','O barulho de um liquidificador ligado é um som:','["Artificial, feito por uma máquina", "Natural", "Que não existe", "De um animal"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t18','ciencias','A natureza dos diferentes sons','treino','Num parque, um cachorro late bem alto e depois late baixinho. O que mudou no som?','["O timbre", "O tipo de animal", "A intensidade", "A cor"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t19','ciencias','Cuidando da saúde auditiva','treino','Qual atitude protege a audição?','["Ouvir música no volume máximo", "Dormir com fone de ouvido", "Limpar a orelha com objetos pontudos", "Usar o fone com volume abaixo da metade"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t20','ciencias','Cuidando da saúde auditiva','treino','Por que não devemos colocar objetos pontudos na orelha?','["Porque podem machucar a orelha e o tímpano", "Porque deixam a orelha suja", "Porque fazem cócegas", "Porque é feio"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t21','ciencias','Cuidando da saúde auditiva','treino','O médico que cuida dos ouvidos se chama:','["Dentista", "Oftalmologista", "Otorrinolaringologista", "Veterinário"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t22','ciencias','Cuidando da saúde auditiva','treino','Ficar muito tempo perto de sons muito fortes pode:','["Melhorar a audição", "Prejudicar a audição", "Deixar a voz mais bonita", "Não fazer nada"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t23','ciencias','Saiba mais: o que é deficiência auditiva?','treino','Deficiência auditiva é:','["Ouvir sons muito agudos", "Não gostar de música", "Ter a voz rouca", "Perder parte ou toda a audição"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t24','ciencias','Saiba mais: o que é deficiência auditiva?','treino','Como se chama a língua de sinais usada no Brasil?','["Libras", "Braile", "Inglês", "Código Morse"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t25','ciencias','Saiba mais: o que é deficiência auditiva?','treino','Em alguns programas de TV aparece uma pessoa fazendo sinais com as mãos no canto da tela. Ela é:','["Uma apresentadora de esportes", "Uma intérprete de Libras", "Uma maestra", "Uma dançarina"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t26','ciencias','Hora do texto: a poluição visual e a auditiva','treino','Poluição sonora é:','["Barulho exagerado que faz mal à saúde e ao sossego", "Lixo jogado no rio", "Fumaça das fábricas", "Uma música bonita"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t27','ciencias','Hora do texto: a poluição visual e a auditiva','treino','Uma rua com muitos cartazes, placas e telas luminosas, todos juntos, tem:','["Poluição da água", "Poluição do solo", "Poluição visual", "Nenhuma poluição"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-t28','ciencias','Hora do texto: a poluição visual e a auditiva','treino','Qual destes é um exemplo de poluição sonora na cidade?','["Um jardim florido", "Carros buzinando sem parar", "Uma biblioteca silenciosa", "Uma árvore balançando"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p01','ciencias','Como percebemos o mundo: som e audição','prova','Qual caminho o som faz até ser entendido por nós?','["Cérebro → orelha → tímpano", "Boca → nariz → cérebro", "Orelha → tímpano → nervo auditivo → cérebro", "Olho → orelha → boca"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p02','ciencias','Como percebemos o mundo: som e audição','prova','O som pode viajar:','["Só pelo ar", "Pelo ar, pela água e pelos objetos sólidos", "Só pela água", "Só pela luz"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p03','ciencias','Propriedades do som','prova','Duas crianças cantam a mesma música, na mesma altura e no mesmo volume, e mesmo assim sabemos quem é quem. Isso acontece por causa do:','["Timbre", "Volume", "Tempo", "Tamanho"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p04','ciencias','Propriedades do som','prova','Um bebê chorando bem alto e por muito tempo. Quais propriedades do som aparecem nessa frase?','["Timbre e cor", "Altura e tamanho", "Só o timbre", "Intensidade (alto) e duração (muito tempo)"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p05','ciencias','Propriedades do som','prova','O som de um tambor grande é grosso. Dizemos que ele é:','["Agudo", "Grave", "Curto", "Fraco"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p06','ciencias','Instrumentos musicais e seus diferentes sons','prova','Qual grupo tem só instrumentos de corda?','["Violão, harpa e violino", "Flauta, tuba e trompete", "Tambor, pandeiro e chocalho", "Violão, flauta e tambor"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p07','ciencias','Instrumentos musicais e seus diferentes sons','prova','O chocalho faz som quando:','["Sopramos nele", "Puxamos uma corda", "Chacoalhamos, e o que está dentro bate nas paredes", "Ligamos na tomada"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p08','ciencias','A natureza dos diferentes sons','prova','Em qual lista todos os sons são da natureza?','["Buzina, trovão e vento", "Chuva, trovão e canto de pássaro", "Sirene, latido e motor", "Campainha, rádio e chuva"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p09','ciencias','Cuidando da saúde auditiva','prova','Ana usa fone de ouvido todo dia, com o volume no máximo. O melhor conselho para ela é:','["Continuar assim", "Usar os dois fones ao mesmo tempo", "Dormir com o fone", "Abaixar o volume para menos da metade e fazer pausas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p10','ciencias','Cuidando da saúde auditiva','prova','Qual é um sinal de que alguém pode estar perdendo a audição?','["Pedir sempre para os outros repetirem o que falaram", "Gostar de música", "Falar baixinho", "Dormir cedo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p11','ciencias','Saiba mais: o que é deficiência auditiva?','prova','Uma pessoa que não ouve nada tem:','["Perda parcial da audição", "Visão fraca", "Surdez, que é a perda total da audição", "Voz grave"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-cien-p12','ciencias','Hora do texto: a poluição visual e a auditiva','prova','Por que a poluição sonora é um problema de saúde?','["Porque deixa as ruas sujas", "Porque causa irritação, cansaço e pode prejudicar a audição", "Porque estraga as plantas", "Porque apaga as luzes"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd');
insert into gabarito (questao_id,correta,explicacao) values
  ('juju-cien-t01',1,'O som nasce de uma vibração e precisa de um meio (ar, água ou sólido) para chegar até nós.'),
  ('juju-cien-t02',0,'As orelhas captam as ondas sonoras. Elas funcionam como uma concha que recolhe o som.'),
  ('juju-cien-t03',2,'O tímpano é uma membrana elástica que vibra quando o som passa por ele.'),
  ('juju-cien-t04',3,'O nervo auditivo leva a mensagem até o cérebro, e é o cérebro que identifica o som.'),
  ('juju-cien-t05',1,'São os três menores ossos do corpo humano e ficam na orelha média.'),
  ('juju-cien-t06',2,'O timbre é o "jeitinho" de cada som. Cada pessoa tem um timbre de voz diferente.'),
  ('juju-cien-t07',0,'Intensidade é o volume: o cochicho é fraco, e o grito é forte.'),
  ('juju-cien-t08',2,'Altura diz se o som é agudo (fino) ou grave (grosso). O piado é agudo, e o mugido é grave.'),
  ('juju-cien-t09',1,'Duração é o tempo que o som dura: o apito do trem é longo e o "bip" é curto.'),
  ('juju-cien-t10',3,'Volume é intensidade. Abaixar o volume deixa o som mais fraco.'),
  ('juju-cien-t11',0,'Agudo é o som fino, como o de um apito. Grave é o som grosso, como o de um tambor grande.'),
  ('juju-cien-t12',1,'A flauta é um instrumento de sopro: o ar que sopramos vibra dentro do tubo.'),
  ('juju-cien-t13',2,'No violão, o som vem da vibração das cordas.'),
  ('juju-cien-t14',0,'Na percussão, o som nasce de batidas, raspagem ou agitação. O tambor é tocado com batidas.'),
  ('juju-cien-t15',3,'No saxofone, o músico sopra e o ar vibra dentro do instrumento.'),
  ('juju-cien-t16',1,'Sons naturais vêm da natureza, como o de animais, chuva, vento e rios. Buzina, sirene e campainha são sons feitos por aparelhos.'),
  ('juju-cien-t17',0,'Sons artificiais são produzidos por máquinas e objetos criados pelas pessoas.'),
  ('juju-cien-t18',2,'Continua sendo o mesmo cachorro, então o timbre é o mesmo. Mudou o volume, que é a intensidade.'),
  ('juju-cien-t19',3,'Volume baixo no fone protege a orelha. Som muito forte pode machucar a audição com o tempo.'),
  ('juju-cien-t20',0,'Objetos pontudos podem ferir a orelha por dentro, inclusive o tímpano.'),
  ('juju-cien-t21',2,'O otorrinolaringologista cuida de ouvido, nariz e garganta. É bom ir pelo menos uma vez por ano.'),
  ('juju-cien-t22',1,'Sons muito intensos, ouvidos por muito tempo, podem causar perda de audição.'),
  ('juju-cien-t23',3,'É a perda parcial ou total da audição. Quando a perda é total, chamamos de surdez.'),
  ('juju-cien-t24',0,'Libras é a Língua Brasileira de Sinais. Ela usa as mãos e o rosto para conversar.'),
  ('juju-cien-t25',1,'A intérprete traduz o que é falado para Libras, para que pessoas surdas também entendam.'),
  ('juju-cien-t26',0,'Barulho demais, como buzinas, obras e som alto, prejudica a saúde e o bem-estar das pessoas.'),
  ('juju-cien-t27',2,'Poluição visual é quando há informação demais para os olhos, como excesso de propagandas.'),
  ('juju-cien-t28',1,'O trânsito barulhento, com muitas buzinas, é uma das maiores causas de poluição sonora nas cidades.'),
  ('juju-cien-p01',2,'A orelha capta o som, o tímpano vibra, o nervo auditivo leva a mensagem e o cérebro entende.'),
  ('juju-cien-p02',1,'O som precisa de um meio para viajar: gases como o ar, líquidos como a água ou sólidos.'),
  ('juju-cien-p03',0,'Cada pessoa tem um timbre de voz único, como uma impressão digital.'),
  ('juju-cien-p04',3,'"Bem alto" fala do volume, que é intensidade. "Por muito tempo" fala da duração.'),
  ('juju-cien-p05',1,'Som grosso é grave. Som fino é agudo.'),
  ('juju-cien-p06',0,'Violão, harpa e violino produzem som pela vibração das cordas.'),
  ('juju-cien-p07',2,'O chocalho é de percussão: o som nasce quando agitamos o instrumento.'),
  ('juju-cien-p08',1,'Chuva, trovão e canto de pássaro vêm da natureza. Buzina, sirene, motor, campainha e rádio são sons artificiais.'),
  ('juju-cien-p09',3,'Volume alto por muito tempo pode causar perda de audição. Volume baixo e pausas protegem a orelha.'),
  ('juju-cien-p10',0,'Precisar que repitam sempre pode ser sinal de perda auditiva. Nesse caso, é bom procurar um médico.'),
  ('juju-cien-p11',2,'Quando a perda da audição é total, chamamos de surdez.'),
  ('juju-cien-p12',1,'Barulho demais tira o sossego, deixa as pessoas irritadas e pode fazer mal à audição.');
